import React, { useState, useMemo, useEffect } from 'react';
import { TrendingUp, TrendingDown, Clock, Target, AlertCircle, CheckCircle, XCircle, BarChart3, Activity, ArrowUpRight, ArrowDownRight, Calendar, RefreshCw, PieChart, LineChart, IndianRupee } from 'lucide-react';

const TradingDashboard = () => {
  const [activeStrategy, setActiveStrategy] = useState('ALL');
  const [activeTab, setActiveTab] = useState('table');
  const [sortConfig, setSortConfig] = useState({ key: 'date', direction: 'desc' });
  const [tradesData, setTradesData] = useState([]);
  const [stats, setStats] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [lastUpdated, setLastUpdated] = useState(null);
  const [logoError, setLogoError] = useState(false);
  const [selectedDate, setSelectedDate] = useState('ALL');

  // API Configuration
  const API_BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:3001/api';

  // Fetch trades from backend
  const fetchTrades = async () => {
    setLoading(true);
    setError(null);

    try {
      const response = await fetch(`${API_BASE_URL}/trades`);
      const data = await response.json();

      if (data.success) {
        setTradesData(data.trades);
        setStats(data.stats);
        setLastUpdated(new Date());
      } else {
        setError(data.error || 'Failed to fetch trades');
      }
    } catch (err) {
      setError('Unable to connect to backend server. Make sure it\'s running on port 3001.');
      console.error('Fetch error:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchTrades();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const filteredTrades = useMemo(() => {
    let filtered = tradesData;

    // Filter by strategy
    if (activeStrategy !== 'ALL') {
      filtered = filtered.filter(trade => trade.strategy === activeStrategy);
    }

    // Filter by date
    if (selectedDate !== 'ALL') {
      filtered = filtered.filter(trade => trade.date === selectedDate);
    }

    return filtered;
  }, [tradesData, activeStrategy, selectedDate]);

  const currentStats = useMemo(() => {
    // If date is selected, calculate stats from filtered trades
    // Otherwise, use pre-calculated stats from backend
    if (selectedDate !== 'ALL') {
      console.log(`📊 Calculating stats for selected date: ${selectedDate}`);
      // Calculate stats dynamically from filtered trades
      const trades = filteredTrades;
      if (trades.length === 0) {
        return {
          totalTrades: 0,
          totalPnL: 0,
          winners: 0,
          losers: 0,
          breakeven: 0,
          winRate: 0,
          avgProfit: 0,
          avgLoss: 0,
          avgPnLPerTrade: 0
        };
      }

      const totalPnL = trades.reduce((sum, t) => sum + t.net_pnl, 0);
      const winners = trades.filter(t => t.net_pnl > 0);
      const losers = trades.filter(t => t.net_pnl < 0);
      const breakeven = trades.filter(t => t.net_pnl === 0);
      const winRate = (winners.length / trades.length) * 100;
      const avgProfit = winners.length > 0 ? winners.reduce((sum, t) => sum + t.net_pnl, 0) / winners.length : 0;
      const avgLoss = losers.length > 0 ? losers.reduce((sum, t) => sum + t.net_pnl, 0) / losers.length : 0;
      const avgPnLPerTrade = totalPnL / trades.length;

      const calculatedStats = {
        totalTrades: trades.length,
        totalPnL,
        winners: winners.length,
        losers: losers.length,
        breakeven: breakeven.length,
        winRate,
        avgProfit,
        avgLoss,
        avgPnLPerTrade
      };

      console.log(`   ✓ Total Trades: ${calculatedStats.totalTrades}`);
      console.log(`   ✓ Net PnL: ₹${calculatedStats.totalPnL.toFixed(2)}`);
      console.log(`   ✓ Win Rate: ${calculatedStats.winRate.toFixed(2)}%`);
      console.log(`   ✓ Avg Win: ₹${calculatedStats.avgProfit.toFixed(2)}, Avg Loss: ₹${calculatedStats.avgLoss.toFixed(2)}`);

      return calculatedStats;
    }

    // No date filter - use pre-calculated stats
    if (!stats) return null;
    return stats[activeStrategy] || stats.ALL;
  }, [stats, activeStrategy, selectedDate, filteredTrades]);

  // Set default sort: desc for all (show latest first), with optional Blaze customization
  useEffect(() => {
    if (activeStrategy === 'Blaze') {
      // If user specifically wants Blaze sorted ascending by entry time, we keep it
      // but the requirement "latest at first" suggests 'desc' might be better for all.
      // However, previous request was 'asc' for Blaze. I'll switch it to 'desc' to satisfy "latest at first".
      setSortConfig({ key: 'entry_time', direction: 'desc' });
    } else {
      setSortConfig({ key: 'date', direction: 'desc' });
    }
  }, [activeStrategy]);

  const handleSort = (key) => {
    setSortConfig({
      key,
      direction: sortConfig.key === key && sortConfig.direction === 'asc' ? 'desc' : 'asc'
    });
  };

  const sortedTrades = useMemo(() => {
    const sorted = [...filteredTrades];

    // Helper to parse time strings like "11:53:07" to comparable values
    const parseTimeString = (timeStr) => {
      if (!timeStr) return 0;
      // Handle HH:MM:SS format
      if (/^\d{1,2}:\d{2}:\d{2}$/.test(timeStr)) {
        const [h, m, s] = timeStr.split(':').map(Number);
        return h * 3600 + m * 60 + s;
      }
      // Handle HH:MM format
      if (/^\d{1,2}:\d{2}$/.test(timeStr)) {
        const [h, m] = timeStr.split(':').map(Number);
        return h * 3600 + m * 60;
      }
      // Fallback to Date parsing
      const d = new Date(timeStr);
      return isNaN(d.getTime()) ? 0 : d.getTime();
    };

    sorted.sort((a, b) => {
      let aVal = a[sortConfig.key];
      let bVal = b[sortConfig.key];

      if (sortConfig.key === 'entry_time' || sortConfig.key === 'exit_time') {
        aVal = parseTimeString(aVal);
        bVal = parseTimeString(bVal);
      } else if (sortConfig.key === 'date') {
        aVal = new Date(aVal);
        bVal = new Date(bVal);
      }

      if (aVal < bVal) return sortConfig.direction === 'asc' ? -1 : 1;
      if (aVal > bVal) return sortConfig.direction === 'asc' ? 1 : -1;
      return 0;
    });
    return sorted;
  }, [filteredTrades, sortConfig]);

  const tradesByDate = useMemo(() => {
    const grouped = {};
    filteredTrades.forEach(trade => {
      const date = trade.date;
      if (!grouped[date]) {
        grouped[date] = [];
      }
      grouped[date].push(trade);
    });
    return grouped;
  }, [filteredTrades]);

  const dailyPnL = useMemo(() => {
    const daily = [];
    Object.keys(tradesByDate).sort().forEach(date => {
      const trades = tradesByDate[date];
      const pnl = trades.reduce((sum, t) => sum + t.net_pnl, 0);
      const winners = trades.filter(t => t.net_pnl > 0).length;
      const losers = trades.filter(t => t.net_pnl < 0).length;
      daily.push({ date, pnl, trades: trades.length, winners, losers });
    });
    return daily;
  }, [tradesByDate]);

  const cumulativePnL = useMemo(() => {
    let cumulative = 0;
    return dailyPnL.map(day => {
      cumulative += day.pnl;
      return { ...day, cumulative };
    });
  }, [dailyPnL]);

  // Get unique dates for filter dropdown
  const uniqueDates = useMemo(() => {
    const dates = [...new Set(tradesData.map(trade => trade.date))].filter(Boolean).sort().reverse();
    return dates;
  }, [tradesData]);

  // Get strategy display name and position type
  const getStrategyDisplay = (strategy) => {
    const displays = {
      'iTrack': { name: 'iTrack', subtitle: 'Live', positionType: 'SHORT' },
      'TrendFlo': { name: 'TrendFlo', subtitle: 'Paper', positionType: 'LONG' },
      'GBlast': { name: 'G-Blast', subtitle: 'Paper', positionType: 'OPTIONS' },
      'GBlastV2': { name: 'G-Blast (v2)', subtitle: 'Paper', positionType: 'OPTIONS' },
      'GBlastV3': { name: 'G-Blast (v3)', subtitle: 'Paper', positionType: 'OPTIONS' },
      'Blaze': { name: 'Blaze (V1)', subtitle: 'Paper', positionType: 'OPTIONS' },
      'BlazeV2': { name: 'Blaze (V2)', subtitle: 'Paper', positionType: 'OPTIONS' },
      'BlazeV3': { name: 'Blaze (V3)', subtitle: 'Paper', positionType: 'OPTIONS' },
      'BlazeV4': { name: 'Blaze (V4)', subtitle: 'Paper', positionType: 'OPTIONS' }
    };
    return displays[strategy] || { name: strategy, subtitle: '', positionType: '' };
  };

  const formatTime = (timestamp) => {
    try {
      if (!timestamp) return 'N/A';

      // Handle HH:MM:SS format (e.g., "11:53:07", "12:03:22")
      if (/^\d{1,2}:\d{2}:\d{2}$/.test(timestamp)) {
        const [hours, minutes] = timestamp.split(':').map(Number);
        const period = hours >= 12 ? 'pm' : 'am';
        const displayHour = hours % 12 || 12;
        return `${displayHour}:${minutes.toString().padStart(2, '0')} ${period}`;
      }

      // Handle MM:SS.ms format (e.g., "53:04.3" from old Blaze CSV) - just display as MM:SS
      if (/^\d{1,2}:\d{2}\.\d+$/.test(timestamp)) {
        const [minSec] = timestamp.split('.');
        return minSec;
      }

      // Handle simple HH:MM format
      if (/^\d{1,2}:\d{2}$/.test(timestamp)) {
        const [hours, minutes] = timestamp.split(':').map(Number);
        const period = hours >= 12 ? 'pm' : 'am';
        const displayHour = hours % 12 || 12;
        return `${displayHour}:${minutes.toString().padStart(2, '0')} ${period}`;
      }

      const date = new Date(timestamp);
      if (isNaN(date.getTime())) return timestamp;
      return date.toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit', hour12: true });
    } catch {
      return timestamp || 'N/A';
    }
  };

  const formatDate = (date) => {
    if (!date) return 'N/A';
    try {
      const d = new Date(date);
      if (isNaN(d.getTime())) return date;
      return d.toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' });
    } catch {
      return date;
    }
  };

  const getEventLabel = (date) => {
    const eventMap = {
      '2026-02-03': { label: 'IND - US Trade Deal', icon: Activity, color: 'from-blue-600 to-indigo-700' },
      '2026-02-01': { label: 'IND - Budget Day', icon: IndianRupee, color: 'from-orange-500 to-red-600' }
    };
    return eventMap[date] || null;
  };

  const formatPrice = (price) => {
    return `₹${price.toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  };

  const formatPnL = (pnl) => {
    const sign = pnl >= 0 ? '+' : '';
    return `${sign}₹${Math.abs(pnl).toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  };

  const formatPercentage = (pct) => {
    return `${pct >= 0 ? '+' : ''}${pct.toFixed(2)}%`;
  };

  const getExitReasonDisplay = (reason) => {
    const reasonMap = {
      'PROFIT_TRAILING_STOP_5MIN': 'Trailing Stop',
      'HARD_STOP_LOSS_915': 'Stop Loss',
      'EOD_EXIT': 'EOD Exit',
      'SESSION_END': 'Session End'
    };
    return reasonMap[reason] || reason.replace(/_/g, ' ');
  };

  const getExitReasonColor = (reason) => {
    if (reason.includes('PROFIT') || reason.includes('TRAILING')) return 'text-emerald-600';
    if (reason.includes('STOP_LOSS')) return 'text-red-600';
    return 'text-gray-600';
  };

  // Show loader for minimum 1.5 seconds for better UX
  useEffect(() => {
    if (!loading && tradesData.length > 0) {
      const minLoadTime = 1500; // 1.5 seconds
      const loadEndTime = Date.now();
      const loadStartTime = loadEndTime - (lastUpdated ? 0 : minLoadTime);
      const remainingTime = Math.max(0, minLoadTime - (loadEndTime - loadStartTime));

      if (remainingTime > 0) {
        setTimeout(() => {
          setLoading(false);
        }, remainingTime);
      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [tradesData]);

  if (loading && tradesData.length === 0) {
    return (
      <div className="min-h-screen flex items-center justify-center" style={{ background: '#eaf4f7' }}>
        <div className="text-center">
          {/* Custom Bar Loader */}
          <div className="mb-4">
            <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 120 100" width="200" height="166" style={{ display: 'block', margin: '0 auto' }}>
              {/* Bar 1 */}
              <rect x="12" y="60" width="10" height="40" fill="#034C8C" rx="1">
                <animate attributeName="height" values="40;70;40" dur="1s" begin="0s" repeatCount="indefinite"
                  keyTimes="0;0.5;1" calcMode="spline" keySplines="0.4 0 0.2 1;0.4 0 0.2 1" />
                <animate attributeName="y" values="60;30;60" dur="1s" begin="0s" repeatCount="indefinite"
                  keyTimes="0;0.5;1" calcMode="spline" keySplines="0.4 0 0.2 1;0.4 0 0.2 1" />
              </rect>
              {/* Bar 2 */}
              <rect x="37" y="60" width="10" height="40" fill="#03738C" rx="1">
                <animate attributeName="height" values="40;60;40" dur="1s" begin="0.18s" repeatCount="indefinite"
                  keyTimes="0;0.5;1" calcMode="spline" keySplines="0.4 0 0.2 1;0.4 0 0.2 1" />
                <animate attributeName="y" values="60;40;60" dur="1s" begin="0.18s" repeatCount="indefinite"
                  keyTimes="0;0.5;1" calcMode="spline" keySplines="0.4 0 0.2 1;0.4 0 0.2 1" />
              </rect>
              {/* Bar 3 */}
              <rect x="62" y="60" width="10" height="40" fill="#038C8C" rx="1">
                <animate attributeName="height" values="40;80;40" dur="1s" begin="0.36s" repeatCount="indefinite"
                  keyTimes="0;0.5;1" calcMode="spline" keySplines="0.4 0 0.2 1;0.4 0 0.2 1" />
                <animate attributeName="y" values="60;20;60" dur="1s" begin="0.36s" repeatCount="indefinite"
