                      }}
                    />
                  </div>
                  <p className={`text-sm mt-2 font-semibold ${(stats.BlazeV3?.totalPnL || 0) >= 0 ? 'text-emerald-600' : 'text-red-600'}`}>
                    P&L: {formatPnL(stats.BlazeV3?.totalPnL || 0)}
                  </p>
                </div>
                <div>
                  <div className="flex justify-between mb-2">
