                    <span className="font-bold" style={{ color: '#1762C7' }}>{stats.BlazeV4?.totalTrades || 0} trades</span>
                  </div>
                  <div className="h-4 bg-gray-200 rounded-full overflow-hidden">
                    <div
                      className="h-full"
                      style={{
